:root {
  --ink: #2c1a0e;
  --parchment: #f0e6cc;
  --parchment-dark: #d9c99a;
  --border-brown: #7a4f2a;
  --accent-ruby: #a0272a;
  --accent-cobalt: #1a3a6b;
  --accent-amber: #c87c0a;
  --accent-sage: #3a6645;
  --accent-violet: #5c3070;
  --accent-sky: #2a7aab;
  --label-muted: #7a5c3a;
  --badge-bg: #1a3a6b;
  --badge-text: #f0e6cc;
  --footer-line: #b89a5a;
}

article.commission-tag {
  background-color: var(--parchment);
  border: 2px solid var(--border-brown);
  border-radius: 6px;
  width: 460px;
  padding: 0;
  overflow: hidden;
  font-size: 13px;
  color: var(--ink);
}

.tag-header {
  background-color: var(--border-brown);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
}

.studio-label {
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.18em;
  color: var(--parchment);
}

.tag-number {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.1em;
  color: var(--parchment-dark);
}

.tag-body {
  display: flex;
  flex-direction: row;
  gap: 0;
  padding: 16px;
  align-items: flex-start;
}

.glass-preview {
  display: grid;
  grid-template-columns: repeat(3, 34px);
  grid-template-rows: repeat(2, 34px);
  gap: 3px;
  flex-shrink: 0;
  margin-right: 18px;
  border: 2px solid var(--border-brown);
  padding: 4px;
  border-radius: 4px;
  background-color: var(--parchment-dark);
}

.pane {
  border-radius: 2px;
  border: 1px solid var(--ink);
  opacity: 0.88;
}

.pane-a { background-color: var(--accent-ruby); border-radius: 50%; }
.pane-b { background-color: var(--accent-cobalt); }
.pane-c { background-color: var(--accent-amber); border-radius: 2px 14px 2px 14px; }
.pane-d { background-color: var(--accent-sage); border-radius: 14px 2px 14px 2px; }
.pane-e { background-color: var(--accent-violet); }
.pane-f { background-color: var(--accent-sky); border-radius: 50%; }

.commission-details {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.detail-row {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: baseline;
  border-bottom: 1px dashed var(--parchment-dark);
  padding-bottom: 4px;
}

.detail-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--label-muted);
}

.detail-value {
  font-size: 13px;
  font-weight: 500;
  color: var(--ink);
}

.tag-footer {
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  border-top: 2px solid var(--footer-line);
  padding: 8px 16px;
  background-color: var(--parchment-dark);
}

.status-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  padding: 3px 10px;
  border-radius: 3px;
  text-transform: uppercase;
}

.artisan-sig {
  font-size: 12px;
  color: var(--label-muted);
}

.artisan-sig em {
  font-style: italic;
  color: var(--ink);
  font-weight: 600;
}
